<?php
declare(strict_types=1);
namespace App\Repository;
use App\Entity\User; use Doctrine\Bundle\DoctrineBundle\Repository\ServiceEntityRepository; use Doctrine\Persistence\ManagerRegistry; use Symfony\Component\Security\Core\User\PasswordUpgraderInterface; use Symfony\Component\Security\Core\User\PasswordAuthenticatedUserInterface;
/** @extends ServiceEntityRepository<User> */ final class UserRepository extends ServiceEntityRepository implements PasswordUpgraderInterface { public function __construct(ManagerRegistry $r){parent::__construct($r,User::class);} public function upgradePassword(PasswordAuthenticatedUserInterface $user,string $hash):void{if($user instanceof User){$user->setPassword($hash);$this->getEntityManager()->flush();}} /** @return list<User> */ public function findTrainers():array{return $this->createQueryBuilder('u')->andWhere('u.trainer = true')->andWhere('u.active = true')->orderBy('u.id','ASC')->getQuery()->getResult();} /** @return list<User> */ public function findContactPeople():array{return $this->createQueryBuilder('u')->addSelect('d')->join('u.departments','d')->andWhere('u.contactPerson = true')->andWhere('u.active = true')->orderBy('u.lastName','ASC')->addOrderBy('u.firstName','ASC')->getQuery()->getResult();} }
